//
// Collate, fixmate, sort and markdup using Samtools
//

include { SAMTOOLS_COLLATE } from 'nf-core/samtools/collate'
include { SAMTOOLS_FIXMATE } from 'nf-core/samtools/fixmate'
include { SAMTOOLS_SORT    } from 'nf-core/samtools/sort'
include { SAMTOOLS_MARKDUP } from 'nf-core/samtools/markdup'


workflow BAM_MARKDUPLICATES_SAMTOOLS {
    take:
    ch_bam // channel: [ val(meta), [ bam ] ]
    ch_fasta_fai // channel: [ val(meta), [ fasta ], [fai] ]

    main:

    SAMTOOLS_COLLATE(ch_bam, ch_fasta_fai)

    SAMTOOLS_FIXMATE(SAMTOOLS_COLLATE.out.bam, ch_fasta_fai)

    SAMTOOLS_SORT(
        SAMTOOLS_FIXMATE.out.bam,
        ch_fasta_fai,
        '',
    )

    SAMTOOLS_MARKDUP(SAMTOOLS_SORT.out.bam, ch_fasta_fai)

    emit:
    bam = SAMTOOLS_MARKDUP.out.bam // channel: [ val(meta), [ bam ] ]
}

nextflow_workflow {

    name "Test Workflow BAM_MARKDUPLICATES_SAMTOOLS"
    config "./nextflow.config"
    script "../main.nf"
    workflow "BAM_MARKDUPLICATES_SAMTOOLS"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bam_markduplicates_samtools"
    tag "bam_markduplicates_samtools"

    tag "samtools"
    tag "samtools/collate"
    tag "samtools/fixmate"
    tag "samtools/sort"
    tag "samtools/markdup"

    test("sarscov2 - bam - fasta") {
        when {
            workflow {
                """
                input[0] = [
                    [id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists:true)
                ]
                input[1] = channel.of([
                    [id:'fasta'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists:true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists:true)
                ])
                """
            }
        }
        then {
            assert workflow.success
            assert snapshot(bam(workflow.out.bam[0][1]).getReadsMD5()).match()
        }
    }

    test("sarscov2 - bam - fasta -- stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = [
                    [id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists:true)
                ]
                input[1] = channel.of([
                    [id:'fasta'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists:true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists:true)
                ])
                """
            }
        }
        then {
            assert workflow.success
            assert snapshot(sanitizeOutput(workflow.out)).match()
        }
    }
}

process {
    withName: SAMTOOLS_COLLATE {
        ext.prefix = { "${meta.id}.collate" }
    }

    withName: SAMTOOLS_FIXMATE {
        ext.prefix = { "${meta.id}.fixmate" }
    }

    withName: SAMTOOLS_SORT {
        ext.prefix = { "${meta.id}.sort" }
    }

    withName: SAMTOOLS_MARKDUP {
        ext.prefix = { "${meta.id}.markdup" }
    }
}
